//! Request-only static tile role. No animation is constructed or evaluated.
use crate::{
    types::{invalid, stopped},
    *,
};

/// Immutable sealed child under a live mapped continuation. Private backing
/// tables prevent arbitrary scene lookup and any conversion to a ready frame.
/// ```compile_fail
/// use vexel_scene::*;
/// fn ready(v: StaticPatternView<'_>) { FrameBuilder::new(v, 1024).unwrap(); }
/// ```
/// ```compile_fail
/// use vexel_scene::*;
/// fn parent(v: StaticPatternView<'_>, parent: SceneId) {
///     v.input().scene(parent);
/// }
/// ```
/// ```compile_fail
/// use vexel_scene::*;
/// fn animation(v: StaticPatternView<'_>) { v.input().animation(); }
/// ```
/// ```compile_fail,E0502
/// use vexel_scene::*;
/// fn mutate(b: &mut SceneBuilder, d: &DraftToken, s: &DecodeSource<'_>,
///     child: SceneId, desc: PatternDescriptor, map: PatternMapping, shape: ShapeId,
///     t: &mut PatternTickets, j: &RasterJob, c: &mut dyn WorkControl) {
///     let request = t.request_mapped_static(b, d, s, child, desc, map, shape,
///         PaintChannel::Fill, j, c).unwrap();
///     b.abort_request(d).unwrap();
///     request.child().input().shapes();
/// }
/// ```
/// ```compile_fail,E0505
/// use vexel_scene::*;
/// fn freeze(b: SceneBuilder, d: &DraftToken, s: &DecodeSource<'_>,
///     child: SceneId, desc: PatternDescriptor, map: PatternMapping, shape: ShapeId,
///     t: &mut PatternTickets, j: &RasterJob, c: &mut dyn WorkControl) {
///     let request = t.request_mapped_static(&b, d, s, child, desc, map, shape,
///         PaintChannel::Fill, j, c).unwrap();
///     b.freeze().unwrap();
///     request.child().input().shapes();
/// }
/// ```
#[derive(Clone, Copy)]
pub struct StaticPatternView<'a> {
    pub(crate) input: RasterInput<'a>,
}
impl<'a> StaticPatternView<'a> {
    pub fn input(self) -> RasterInput<'a> {
        self.input
    }
}
#[derive(Clone, Copy)]
pub(crate) struct StaticScope {
    pub generation: u64,
    pub job: LedgerIdentity,
    pub draft: u64,
    pub request: RequestToken,
    pub ticket: PatternTicket,
}
pub struct StaticPatternRequest<'a> {
    pub(crate) ticket: PatternTicket,
    pub(crate) child: StaticPatternView<'a>,
    pub(crate) descriptor: PatternDescriptor,
}
impl<'a> StaticPatternRequest<'a> {
    pub fn ticket(&self) -> PatternTicket {
        self.ticket
    }
    pub fn child(&self) -> StaticPatternView<'a> {
        self.child
    }
    pub fn descriptor(&self) -> PatternDescriptor {
        self.descriptor
    }
}
impl PatternTickets {
    /// Borrows the builder until the tile render ends. The caller then drops the
    /// request and publishes same-job output through `complete_mapped`.
    pub fn request_mapped_static<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<StaticPatternRequest<'a>> {
        builder.draft_index(draft)?;
        let request_identity = builder.static_request_child(child)?;
        let view = builder.traversal_scene(child)?;
        let viewport = view
            .viewport
            .ok_or_else(|| invalid(descriptor.error_offset))?;
        crate::validate::viewport(viewport)?;
        // Original C's tile viewport: raster dimensions, origin zero, tile
        // extent and preserveAspectRatio=none. No fabricated parent viewport.
        if viewport.width != descriptor.width
            || viewport.height != descriptor.height
            || viewport.view_x != 0.
            || viewport.view_y != 0.
            || viewport.view_width != descriptor.tile_width
            || viewport.view_height != descriptor.tile_height
            || !viewport.aspect.none
        {
            return Err(invalid(descriptor.error_offset));
        }
        let tables = view.raster_tables(viewport);
        validate_mask_closure(tables, &mut [None; 64], 0, &mut 0, control)?;
        let request = self.request_mapped_view(
            builder, draft, source, child, view, descriptor, mapping, shape, channel, job, control,
        )?;
        let scope = StaticScope {
            generation: builder.generation(),
            job: job.owner_identity(),
            draft: draft.nonce,
            request: request_identity,
            ticket: request.ticket,
        };
        Ok(StaticPatternRequest {
            ticket: request.ticket,
            descriptor,
            child: StaticPatternView {
                input: RasterInput::static_child(tables, scope),
            },
        })
    }
}
fn validate_mask_closure(
    view: SceneView<'_, Viewport, ()>,
    stack: &mut [Option<SceneId>; 64],
    depth: usize,
    visits: &mut usize,
    control: &mut dyn WorkControl,
) -> Result<()> {
    control.checkpoint().map_err(stopped)?;
    if depth == stack.len() || *visits >= 65536 {
        return Err(crate::types::limit(LimitKind::Masks));
    }
    if stack[..depth].contains(&Some(view.id)) {
        return Err(invalid(0));
    }
    *visits = visits
        .checked_add(1)
        .ok_or_else(crate::memory::arithmetic)?;
    stack[depth] = Some(view.id);
    for mask in view.masks {
        control
            .charge(WorkKind::ReferenceProbe, 1)
            .map_err(stopped)?;
        let child = view
            .scene(mask.content)
            .ok_or_else(|| invalid(mask.source_offset))?;
        crate::validate::viewport(child.viewport)?;
        validate_mask_closure(child, stack, depth + 1, visits, control)?;
    }
    // Also require the initial child sealed (scene lookup checks serial/seal).
    view.scene(view.id).ok_or_else(|| invalid(0))?;
    Ok(())
}
//! One bounded request scope inside the current draft. Marks own no prefix data.
//! Discarding a token does not commit: explicitly abort with the outer draft.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RequestToken {
    scene: SceneId,
    draft: u64,
    nonce: u64,
    generation: u64,
}
#[derive(Debug)]
pub(crate) struct ActiveRequest {
    token: RequestToken,
    pub(crate) mark: BuildMark,
    scene_count: usize,
    ignored: [Ignored; 4],
    text_commands: usize,
}
impl SceneBuilder {
    pub(crate) fn request_protects_draft(&self, draft: &DraftToken) -> bool {
        self.request
            .as_ref()
            .is_some_and(|r| r.token.draft == draft.nonce)
    }
    pub(crate) fn request_protects_scene(&self, id: SceneId) -> bool {
        self.request
            .as_ref()
            .is_some_and(|r| id.index() < r.scene_count)
    }
    pub(crate) fn request_identity(&self) -> Option<RequestToken> {
        self.request.as_ref().map(|r| r.token)
    }
    pub fn begin_request(
        &mut self,
        draft: &DraftToken,
        control: &mut dyn WorkControl,
    ) -> Result<RequestToken> {
        self.draft_index(draft)?;
        if self.request.is_some() {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        let token = RequestToken {
            scene: draft.mark.scene,
            draft: draft.nonce,
            nonce: self.serial()?,
            generation: self.generation,
        };
        let mark = self.checkpoint_internal(token.scene)?;
        self.request = Some(ActiveRequest {
            token,
            mark,
            scene_count: self.scenes.len(),
            ignored: self.ignored,
            text_commands: self.text_commands,
        });
        Ok(token)
    }
    fn request_index(&self, draft: &DraftToken, token: RequestToken) -> Result<usize> {
        let i = self.draft_index(draft)?;
        let active = self.request.as_ref().ok_or_else(|| invalid(0))?;
        if active.token != token
            || token.draft != draft.nonce
            || token.scene != draft.mark.scene
            || token.generation != self.generation
        {
            return Err(invalid(0));
        }
        Ok(i)
    }
    /// Failure leaves the request active for unconditional cleanup. Prefix handles
    /// retain their insertion serials; no whole-scene epoch is an ID authority.
    pub fn commit_request(
        &mut self,
        draft: &DraftToken,
        token: RequestToken,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.request_index(draft, token)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::scene(self, token.scene, control)?;
        self.request = None;
        Ok(())
    }
    pub fn rollback_request(&mut self, draft: &DraftToken, token: RequestToken) -> Result<()> {
        let i = self.request_index(draft, token)?;
        let active = self.request.as_ref().ok_or_else(|| invalid(0))?;
        let mut released = 0;
        for scene in &self.scenes[active.scene_count..] {
            released = crate::memory::add(released, scene.storage_bytes()?)?;
        }
        // Prevalidate cleanup arithmetic before taking the checkpoint.
        self.scenes[i]
            .epoch
            .checked_add(1)
            .ok_or_else(crate::memory::arithmetic)?;
        let active = self.request.take().ok_or_else(|| invalid(0))?;
        let mut mark = active.mark;
        mark.epoch = self.scenes[i].epoch;
        self.rollback_internal(mark)?;
        self.scenes.truncate(active.scene_count);
        self.stats.live_bytes -= released;
        self.ignored = active.ignored;
        self.text_commands = active.text_commands;
        Ok(())
    }
    /// Recover an abandoned token. Only the same still-active outer draft can
    /// abort. No control polling, allocation, implicit commit or Drop callback.
    pub fn abort_request(&mut self, draft: &DraftToken) -> Result<()> {
        self.draft_index(draft)?;
        let token = self.request.as_ref().ok_or_else(|| invalid(0))?.token;
        self.rollback_request(draft, token)
    }
}

impl SceneBuilder {
    /// Actual document uses, including cached layouts. Cache admission is separate.
    /// Admit after provider/layout and glyph validation, before outline publication.
    /// The caller must end this request with commit or unconditional rollback.
    pub fn admit_text_commands(
        &mut self,
        draft: &DraftToken,
        commands: usize,
        source_offset: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.draft_index(draft)?;
        if self.request.is_none() || source_offset > self.source.len() {
            return Err(invalid(source_offset));
        }
        // Original subtraction priority: huge input is TextCommands, not arithmetic.
        if commands > DOCUMENT_TEXT_COMMAND_LIMIT - self.text_commands {
            return Err(Diagnostic {
                kind: ErrorKind::Limit(LimitKind::TextCommands),
                offset: source_offset,
            });
        }
        let total = self
            .text_commands
            .checked_add(commands)
            .ok_or_else(crate::memory::arithmetic)?;
        control.checkpoint().map_err(stopped)?;
        self.text_commands = total;
        Ok(())
    }
    pub fn document_text_commands(&self) -> usize {
        self.text_commands
    }
}
pub const DOCUMENT_TEXT_COMMAND_LIMIT: usize = 4 * 1024 * 1024;

impl SceneBuilder {
    pub(crate) fn static_request_child(&self, child: SceneId) -> Result<RequestToken> {
        let active = self.request.as_ref().ok_or_else(|| invalid(0))?;
        if child.index() < active.scene_count { return Err(invalid(0)); }
        Ok(active.token)
    }
}
//! Complete computed plan handoff. Mapping is carried at suspension, never
//! reconstructed by parsing source on resume. Original descriptors stay intact.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PatternMapping {
    pub tile_origin: [f64; 2],
    pub user_to_base: Affine,
    pub pattern_transform: Affine,
    pub user_inverse: Affine,
    pub viewport: [f64; 2],
    pub bounds: [f64; 4],
    pub source_map: SourceMap,
    pub opacity: f64,
}
impl PatternMapping {
    pub fn pixel_inverse(self, descriptor: PatternDescriptor) -> Result<Affine> {
        use vexel_geometry::{affine_compose, affine_valid};
        if !self.tile_origin.into_iter().all(f64::is_finite)
            || !self.viewport.into_iter().all(|v| v.is_finite() && v > 0.)
            || ordered_bounds_extent(self.bounds).is_none()
            || !self.opacity.is_finite()
            || !(0.0..=1.0).contains(&self.opacity)
            || !affine_valid(self.user_inverse)
            || !affine_valid(self.source_map.transform)
        {
            return Err(invalid(descriptor.error_offset));
        }
        // The supplied computed inverse must implement inverse(patternTransform)
        // followed by translation(-tileOrigin), as in the original algorithm.
        let back = affine_compose(self.user_to_base, self.pattern_transform)
            .ok_or_else(|| invalid(descriptor.error_offset))?;
        let expected = [1., 0., 0., 1., -self.tile_origin[0], -self.tile_origin[1]];
        for (a, b) in [back.a, back.b, back.c, back.d, back.e, back.f]
            .into_iter()
            .zip(expected)
        {
            if (a - b).abs() > 1e-9 * a.abs().max(b.abs()).max(1.) {
                return Err(invalid(descriptor.error_offset));
            }
        }
        let scale = Affine {
            a: descriptor.width as f64 / descriptor.tile_width,
            d: descriptor.height as f64 / descriptor.tile_height,
            b: 0.,
            c: 0.,
            e: 0.,
            f: 0.,
        };
        affine_compose(scale, self.user_to_base).ok_or_else(|| invalid(descriptor.error_offset))
    }
}
#[derive(Debug, Clone, Copy)]
pub(crate) struct PatternContinuation {
    mapping: PatternMapping,
    parent: SceneId,
    shape: ShapeId,
    channel: PaintChannel,
    draft: u64,
    generation: u64,
    request: Option<RequestToken>,
    job: LedgerIdentity,
}
impl PatternTickets {
    pub fn request_mapped<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a>> {
        let child_view = builder.scene(child)?;
        self.request_mapped_view(builder, draft, source, child, child_view, descriptor,
            mapping, shape, channel, job, control)
    }
    pub fn request_mapped_traversal<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a, Option<Viewport>, Option<AnimationView<'a>>>> {
        let child_view = builder.traversal_scene(child)?;
        self.request_mapped_view(builder, draft, source, child, child_view, descriptor,
            mapping, shape, channel, job, control)
    }
    pub(crate) fn request_mapped_view<'a, V: ViewportRead, A: Copy>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        child_view: SceneView<'a, V, A>,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a, V, A>> {
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, shape.index(), builder.scenes[i].shapes.len())?;
        job.validate_source(builder.source_owner())?;
        if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
            return Err(invalid(0));
        }
        let definition = source.element(
            descriptor.definition,
            crate::memory::add(descriptor.definition.0, 1)?,
            control,
        )?;
        if definition.tokens()[descriptor.definition.0]
            .local_name
            .slice(source.source())
            != Some(b"pattern")
        {
            return Err(invalid(descriptor.error_offset));
        }
        let value = builder
            .traversal_scene(draft.mark.scene)?
            .shape(shape)
            .copied()
            .ok_or_else(|| invalid(0))?;
        if value.source != mapping.source_map
            || mapping
                .source_map
                .element
                .slice(builder.source_owner())
                .is_none()
        {
            return Err(invalid(0));
        }
        mapping.pixel_inverse(descriptor)?;
        if child == draft.mark.scene || child.index() < draft.scene_count {
            return Err(invalid(0));
        }
        let request = self.request(child_view, descriptor, control)?;
        self.pending.as_mut().ok_or_else(|| invalid(0))?.production = Some(PatternContinuation {
            mapping,
            parent: draft.mark.scene,
            shape,
            channel,
            draft: draft.nonce,
            generation: builder.generation,
            request: builder.request_identity(),
            job: job.owner_identity(),
        });
        Ok(request)
    }
    /// Transfer admitted job output directly into the builder's owned pattern;
    /// then publish and attach the exact fill/stroke mapping. No raw Vec or Tile
    /// escapes this operation. Late errors unwind just this publication suffix.
    pub fn complete_mapped(
        &mut self,
        ticket: PatternTicket,
        builder: &mut SceneBuilder,
        draft: &DraftToken,
        job: &mut RasterJob,
        result: Result<JobRenderOutput>,
        control: &mut dyn WorkControl,
    ) -> Result<(PatternId, usize)> {
        let pending = self.pending.as_ref().ok_or_else(|| invalid(0))?;
        if pending.ticket != ticket {
            return Err(invalid(0));
        }
        let p = pending.production.ok_or_else(|| invalid(0))?;
        let descriptor = pending.descriptor;
        job.validate_source(builder.source_owner())?;
        if builder.owner != p.parent.owner || job.owner_identity() != p.job {
            return Err(invalid(0));
        }
        let child = pending.scene;
        let live = builder.draft_index(draft).is_ok()
            && draft.nonce == p.draft
            && draft.mark.scene == p.parent
            && builder.generation == p.generation
            && builder.request_identity() == p.request
            && builder
                .traversal_scene(child)
                .is_ok_and(|view| view.scene(child).is_some())
            && builder
                .traversal_scene(p.parent)
                .is_ok_and(|view| view.shape(p.shape).is_some());
        if !live {
            self.pending = None;
            if let Ok(output) = result {
                if output.validate(job).is_ok() {
                    job.release(output.pixels)?;
                }
            }
            return Err(invalid(0));
        }
        let output = match result {
            Ok(output) => output,
            Err(error) => {
                self.pending = None;
                return Err(error);
            }
        };
        output.validate(job)?;
        if output.width != descriptor.width
            || output.height != descriptor.height
            || output.generation != p.generation
        {
            return Err(invalid(0));
        }
        let inverse = p.mapping.pixel_inverse(descriptor)?;
        let mut shape = *builder
            .traversal_scene(p.parent)?
            .shape(p.shape)
            .ok_or_else(|| invalid(0))?;
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, p.shape.index(), builder.scenes[i].shapes.len())?;
        let mut mark = builder.checkpoint_internal(p.parent)?;
        let result = (|| {
            control.checkpoint().map_err(stopped)?;
            let id = job.publish_pattern_output(output, builder, p.parent, descriptor, control)?;
            let paint = Paint {
                kind: PaintKind::Pattern,
                spread: Spread::Repeat,
                object_bounding_box: false,
                coordinates: [
                    p.mapping.tile_origin[0],
                    p.mapping.tile_origin[1],
                    descriptor.tile_width,
                    descriptor.tile_height,
                    0.,
                    0.,
                ],
                bounds: p.mapping.bounds,
                user_inverse: p.mapping.user_inverse,
                gradient_inverse: vexel_geometry::affine_identity(),
                stops: TableRange::EMPTY,
                pattern: Some(id),
                pattern_inverse: inverse,
                pattern_opacity: p.mapping.opacity,
            };
            let index = match p.channel {
                PaintChannel::Fill => builder.append_fill_paint(p.parent, paint, control)?,
                PaintChannel::Stroke => builder.append_stroke_paint(p.parent, paint, control)?,
            };
            match p.channel {
                PaintChannel::Fill => shape.fill_paint = Some(index),
                PaintChannel::Stroke => shape.stroke_paint = Some(index),
            }
            builder.finalize_shape(draft, p.shape, shape, control)?;
            Ok((id, index))
        })();
        if result.is_err() {
            mark.epoch = builder.scenes[i].epoch;
            builder.rollback_internal(mark)?;
            // Output may not yet have transferred. Clean it unconditionally.
            if job.slice(output.pixels).is_ok() {
                job.release(output.pixels)?;
            }
        }
        self.pending = None;
        result
    }
}

