/// Complete immutable table view, including checked child lookup and source context.
pub type ViewTables<'a> = SceneView<'a>;
macro_rules! view_handle {
    ($name:ident, $kind:ident, $field:ident, $serial:expr) => {
        /// Retrieve an existing checked handle from this exact immutable view.
        /// Enumeration includes records with no edges and preserves insertion
        /// serials, so rollback/reused slots cannot authorize stale handles.
        pub fn $name(&self, index: usize) -> Option<$kind> {
            self.$field.get(index)?;
            Some($kind {
                owner: self.id.owner,
                scene: self.id.slot,
                slot: u32::try_from(index).ok()?,
                serial: *self.serials[$serial].get(index)?,
            })
        }
    };
}
impl<'a, V: ViewportRead, A: Copy> SceneView<'a, V, A> {
    view_handle!(shape_id, ShapeId, shapes, 0);
    view_handle!(transform_id, TransformId, transforms, 1);
    view_handle!(clip_id, ClipId, clips, 2);
    view_handle!(pattern_id, PatternId, patterns, 3);
    view_handle!(mask_id, MaskId, masks, 4);
    view_handle!(filter_id, FilterId, filters, 5);
    view_handle!(group_id, GroupId, groups, 6);
    pub(crate) fn overlay<'b>(
        &'b self,
        edges: Option<&'b [Edge]>,
        colors: Option<&'b [[u8; 4]]>,
        shapes: Option<&'b [Shape]>,
        fills: Option<&'b [Paint]>,
        strokes: Option<&'b [Paint]>,
        transforms: Option<&'b [TransformFrame]>,
        clips: Option<&'b [Clip]>,
    ) -> SceneView<'b, V, A> {
        let mut view: SceneView<'b, V, A> = *self;
        if let Some(v) = edges {
            view.edges = v;
        }
        if let Some(v) = colors {
            view.edge_colors = v;
        }
        if let Some(v) = shapes {
            view.shapes = v;
        }
        if let Some(v) = fills {
            view.fill_paints = v;
        }
        if let Some(v) = strokes {
            view.stroke_paints = v;
        }
        if let Some(v) = transforms {
            view.transforms = v;
        }
        if let Some(v) = clips {
            view.clips = v;
        }
        view
    }

    pub(crate) fn raster_tables(&self, viewport: Viewport) -> SceneView<'a, Viewport, ()> {
        SceneView { animation: (), viewport,
            scenes: self.scenes,
            source: self.source,
            ignored: self.ignored,
            id: self.id,
            edges: self.edges,
            edge_colors: self.edge_colors,
            edge_shape_ids: self.edge_shape_ids,
            shapes: self.shapes,
            path_subpaths: self.path_subpaths,
            path_segments: self.path_segments,
            path_numbers: self.path_numbers,
            transforms: self.transforms,
            images: self.images,
            groups: self.groups,
            filters: self.filters,
            filter_primitives: self.filter_primitives,
            masks: self.masks,
            patterns: self.patterns,
            fill_paints: self.fill_paints,
            stroke_paints: self.stroke_paints,
            dash_values: self.dash_values,
            stops: self.stops,
            clips: self.clips,
            serials: self.serials,
        }
    }

    pub fn tables(&self) -> SceneView<'a, V, A> {
        *self
    }
    pub fn source(&self) -> &'a [u8] {
        self.source.as_slice()
    }
    pub fn source_owner(&self) -> &'a SourceOwner {
        self.source
    }
    pub fn ignored(&self, kind: IgnoredKind) -> Ignored {
        self.ignored[kind as usize]
    }
    pub fn scene(&self, id: SceneId) -> Option<SceneView<'a, V, A>> {
        let scene = self.scenes.get(id.index())?;
        if id.owner != self.id.owner || id.serial != scene.serial || !scene.sealed {
            return None;
        }
        if id == self.id {
            return Some(*self);
        }
        Some(scene.view(
            self.id.owner,
            id.index(),
            self.scenes,
            self.source,
            self.animation,
            V::from_viewport(scene.viewport)?,
            self.ignored,
        ))
    }
    pub fn fill_paint(&self, id: ShapeId) -> Option<&'a Paint> {
        self.fill_paints.get(self.shape(id)?.fill_paint?)
    }
    pub fn stroke_paint(&self, id: ShapeId) -> Option<&'a Paint> {
        self.stroke_paints.get(self.shape(id)?.stroke_paint?)
    }
    pub fn shape_dashes(&self, id: ShapeId) -> Option<&'a [f64]> {
        self.shape(id)?.stroke.dash_values.slice(self.dash_values)
    }

    pub fn shape(&self, id: ShapeId) -> Option<&'a Shape> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[0].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.shapes.get(id.index())
    }
    pub fn transform(&self, id: TransformId) -> Option<&'a TransformFrame> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[1].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.transforms.get(id.index())
    }
    pub fn clip(&self, id: ClipId) -> Option<&'a Clip> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[2].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.clips.get(id.index())
    }
    pub fn pattern(&self, id: PatternId) -> Option<&'a Pattern> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[3].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.patterns.get(id.index())
    }
    pub fn mask(&self, id: MaskId) -> Option<&'a Mask> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[4].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.masks.get(id.index())
    }
    pub fn filter(&self, id: FilterId) -> Option<&'a Filter> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[5].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.filters.get(id.index())
    }
    pub fn group(&self, id: GroupId) -> Option<&'a OpacityGroup> {
        if id.owner != self.id.owner
            || id.scene != self.id.slot
            || self.serials[6].get(id.index()) != Some(&id.serial)
        {
            return None;
        }
        self.groups.get(id.index())
    }
    pub fn edge_shape(&self, edge: usize) -> Option<ShapeId> {
        let slot = *self.edge_shape_ids.get(edge)?;
        Some(ShapeId {
            owner: self.id.owner,
            scene: self.id.slot,
            slot,
            serial: *self.serials[0].get(slot as usize)?,
        })
    }
}
/// Immutable, source-coherent scene graph suitable for worker ownership transfer.
#[derive(Debug)]
pub struct SceneGraph {
    pub(crate) owner: u64,
    pub(crate) source: SourceOwner,
    pub(crate) generation: u64,
    pub(crate) root: SceneId,
    pub(crate) scenes: Vec<SceneData>,
    pub(crate) animation: OwnedAnimation,
    pub(crate) ignored: [Ignored; 4],
    pub(crate) stats: MemoryStats,
}
impl SceneGraph {
    pub fn scene_id(&self, index: usize) -> Option<SceneId> {
        let scene = self.scenes.get(index)?;
        Some(SceneId {
            owner: self.owner,
            slot: u32::try_from(index).ok()?,
            serial: scene.serial,
        })
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn source(&self) -> &[u8] {
        self.source.as_slice()
    }
    pub fn generation(&self) -> u64 {
        self.generation
    }
    pub fn root(&self) -> SceneView<'_> {
        self.scene(self.root).expect("validated root")
    }
    pub fn scene(&self, id: SceneId) -> Option<SceneView<'_>> {
        let scene = self.scenes.get(id.index())?;
        if id.owner != self.owner || id.serial != scene.serial {
            return None;
        }
        Some(scene.view(
            self.owner,
            id.index(),
            &self.scenes,
            &self.source,
            self.animation.view(),
            scene.viewport?,
            self.ignored,
        ))
    }
    pub fn scene_count(&self) -> usize {
        self.scenes.len()
    }
    pub fn animation(&self) -> AnimationView<'_> {
        self.animation.view()
    }
    pub fn ignored(&self, kind: IgnoredKind) -> Ignored {
        self.ignored[kind as usize]
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
}

// Sealed conversion keeps traversal reads from manufacturing renderable views.
mod read_sealed {
    pub trait Sealed {}
    impl Sealed for super::Viewport {}
    impl Sealed for Option<super::Viewport> {}
}
pub trait ViewportRead: Copy + read_sealed::Sealed {
    #[doc(hidden)]
    fn from_viewport(value: Option<Viewport>) -> Option<Self>;
}
impl ViewportRead for Viewport {
    fn from_viewport(value: Option<Viewport>) -> Option<Self> { value }
}
impl ViewportRead for Option<Viewport> {
    fn from_viewport(value: Option<Viewport>) -> Option<Self> { Some(value) }
}
/// Read-only traversal tables. Neither viewport nor animation is fabricated.
/// This type cannot be passed to frame builders or scalar render APIs.
/// ```compile_fail
/// use vexel_scene::{FrameBuilder, SceneBuilder};
/// fn unfinished_frame(builder: &SceneBuilder) {
///     let read = builder.traversal_scene(builder.root_id()).unwrap();
///     FrameBuilder::new(read, 1024).unwrap();
/// }
/// ```
pub type TraversalView<'a> = SceneView<'a, Option<Viewport>, Option<AnimationView<'a>>>;
impl<'a> SceneView<'a> {
    pub fn animation(&self) -> AnimationView<'a> { self.animation }
}
impl<'a> TraversalView<'a> {
    pub fn parsed_animation(&self) -> Option<AnimationView<'a>> { self.animation }
}

//! Public input fixture only; no runtime/native scalar-renderer claim.
mod support;
use std::sync::Arc;
use support::*;
use vexel_geometry::affine_identity as identity;
use vexel_scene::*;

fn doc(invalid_animation: bool) -> LexicalDocument {
    let mut text = "<svg width=\"100\" height=\"100\"><pattern/><path d=\"M0 0 L1 1 2 3 Z\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"1s\"/></path>".to_owned();
    if invalid_animation {
        for _ in 0..129 {
            text.push_str("<animate attributeName=\"opacity\" values=\"0;1\" dur=\"1s\"/>");
        }
    }
    text.push_str("</svg>");
    LexicalDocument::parse(Arc::new(text.into_bytes()), 1 << 20, &mut Run).unwrap()
}
fn element(d: &LexicalDocument, name: &[u8]) -> ElementId {
    ElementId(d.tokens().iter().position(|t| t.local_name.slice(d.source()) == Some(name)).unwrap())
}
fn descriptor(d: &LexicalDocument) -> PatternDescriptor {
    PatternDescriptor {
        definition: element(d, b"pattern"),
        width: 1,
        height: 1,
        tile_width: 1.,
        tile_height: 1.,
        content_transform: identity(),
        error_offset: 10,
    }
}
fn tile_viewport() -> Viewport {
    let mut v = viewport();
    v.width = 1;
    v.height = 1;
    v.view_width = 1.;
    v.view_height = 1.;
    v.aspect.none = true;
    v
}
fn provisional(d: &LexicalDocument) -> SceneBuilder {
    let mut b = SceneBuilder::provisional(d.source_owner().clone(), 7, Limits::default()).unwrap();
    b.initialize_root(&mut DecodeSource::new(d, &mut Run).unwrap(), element(d, b"svg"), &mut Run).unwrap();
    b
}
fn input(d: &LexicalDocument) -> ShapeInput {
    let mut s = shape(d.source());
    let start = d.source().windows(5).position(|v| v == b"<path").unwrap();
    s.shape.source.element = Span { start, end: d.source().len() - 6 };
    s
}
fn mapping(b: &SceneBuilder, scene: SceneId, shape: ShapeId, bounds: [f64; 4]) -> PatternMapping {
    PatternMapping {
        tile_origin: [0.; 2],
        user_to_base: identity(),
        pattern_transform: identity(),
        user_inverse: identity(),
        viewport: [100.; 2],
        bounds,
        source_map: b.traversal_scene(scene).unwrap().shape(shape).unwrap().source,
        opacity: 0.75,
    }
}
fn job(d: &LexicalDocument) -> RasterJob {
    RasterJob::new(ChargeLedger::new(d.source_owner(), 8 << 20, 65536).unwrap()).unwrap()
}
fn output(job: &mut RasterJob, c: &mut dyn WorkControl) -> Result<JobRenderOutput> {
    let pixels = job.buffer(RasterPool::Output, 4, c)?;
    job.extend(pixels, &[1, 2, 3, 255], c)?;
    Ok(JobRenderOutput { generation: 7, pixels, width: 1, height: 1, stride: 4 })
}

/// Intentional table-consuming fixture; lower production algorithms adopt later.
struct Engine {
    fail: bool,
    calls: usize,
    rich: bool,
}
impl CommonKernelResources for Engine {
    fn paint_sample(&self, _: &Paint, stops: &[PaintStop], _: f64, _: f64, c: &mut dyn WorkControl) -> Result<[u8; 4]> {
        for _ in stops {
            c.charge(WorkKind::PaintVisit, 1).map_err(|_| Diagnostic { kind: ErrorKind::Canceled, offset: 0 })?;
        }
        Ok([1, 2, 3, 255])
    }
    fn clip_contains(&self, v: RasterInput<'_>, id: ClipId, _: f64, _: f64, c: &mut dyn WorkControl) -> Result<bool> {
        self.clip_work_counts(v, id, c).map(|n| n.edges == 0)
    }
    fn clip_boundary_edges(
        &self,
        v: RasterInput<'_>,
        id: ClipId,
        visitor: &mut dyn FnMut(Edge) -> bool,
        c: &mut dyn WorkControl,
    ) -> Result<bool> {
        for e in &v.clip(id).unwrap().geometry.edges {
            c.checkpoint().map_err(|_| Diagnostic { kind: ErrorKind::Canceled, offset: 0 })?;
            if !visitor(*e) {
                return Ok(false);
            }
        }
        Ok(true)
    }
    fn clip_work_counts(&self, v: RasterInput<'_>, id: ClipId, c: &mut dyn WorkControl) -> Result<ClipWorkCounts> {
        c.checkpoint().map_err(|_| Diagnostic { kind: ErrorKind::Canceled, offset: 0 })?;
        let clip = v.clip(id).unwrap();
        Ok(ClipWorkCounts {
            edges: clip.geometry.edges.len(),
            chain_elements: 1,
            child_shapes: clip.geometry.shapes.len(),
        })
    }
    fn stroke_sample_work(
        &self,
        v: RasterInput<'_>,
        id: ShapeId,
        _: ValidatedDashView<'_>,
        _: f64,
        _: f64,
        c: &mut dyn WorkControl,
    ) -> Result<(usize, bool, bool)> {
        c.checkpoint().map_err(|_| Diagnostic { kind: ErrorKind::Canceled, offset: 0 })?;
        Ok((v.shape(id).unwrap().edges.count, false, false))
    }
}
