    LexicalDocument::parse(Arc::new(br#"<svg width="100" height="100"><path d="M0 0 L1 1 2 3 Z"/><text>x</text><image/><pattern/><filter/><g/></svg>"#.to_vec()),1<<20,&mut Run).unwrap()
