fn text(
    ops: &mut dyn ScopedProductionDecodeOperations,
    b: &mut SceneBuilder,
    draft: &DraftToken,
    shared: &DecodeSource<'_>,
    d: &LexicalDocument,
    provider: &mut Provider,
    ledger: &mut ChargeLedger,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    let e = shared.element(element(d, b"text"), d.tokens().len(), &mut Run).unwrap();
    let mut state = TextState::default();
    let mut cache = TextCache::default();
    let map = SourceMap {
        element: Span {
            start: e.tokens()[e.element.0].source.offset,
            end: e.tokens()[e.element.0].source.end().unwrap(),
        },
        transform: identity(),
        transform_node: None,
    };
    decode_scoped_text(
        ops,
        TextDecodeRequest {
            element: e,
            end: e.end,
            source_map: map,
            style: &CssPaint::initial(),
            transform: identity(),
            state: &mut state,
            preserve_space: false,
            provider,
            cache: &mut cache,
            scene: b.root_id(),
            ledger,
        },
        b,
        draft,
        control,
    )
}
