    fn cells(&self, h: JobBuffer<GridCell>, scope: u64) -> Result<&[GridCell]> {
        self.slice_scoped(h, RasterPool::Grid, scope)
    }
    fn references(&self, h: JobBuffer<u32>, scope: u64) -> Result<&[u32]> {
        self.slice_scoped(h, RasterPool::Grid, scope)
    }
}
/// Exclusive job borrow prevents cache mutation, release, finish or teardown.
