+    fn clip_boundary_edges(
+        &self,
+        v: RasterInput<'_>,
+        id: ClipId,
+        visitor: &mut dyn FnMut(Edge) -> bool,
+        c: &mut dyn WorkControl,
+    ) -> Result<bool> {
+        for e in &v.clip(id).unwrap().geometry.edges {
+            c.checkpoint().map_err(|_| Diagnostic { kind: ErrorKind::Canceled, offset: 0 })?;
